'use strict';

/**
 * In-memory storage adapter for express-gamekit.
 * Uses a Map per collection. Supports sync and async operations.
 * 
 * @returns {object} Storage adapter with get, set, delete, and list
 */
function memoryStore() {
  /** @type {Map<string, Map<string, any>>} */
  const collections = new Map();

  function getCollection(name) {
    if (!collections.has(name)) {
      collections.set(name, new Map());
    }
    return collections.get(name);
  }

  return {
    /**
     * Get a document by ID.
     * @param {string} collection
     * @param {string} id
     * @returns {Promise<any|null>}
     */
    async get(collection, id) {
      const col = getCollection(collection);
      const item = col.get(String(id));
      if (!item) return null;
      // Return a deep copy to prevent direct external mutation
      return JSON.parse(JSON.stringify(item));
    },

    /**
     * Store or replace a document.
     * @param {string} collection
     * @param {string} id
     * @param {any} doc
     * @returns {Promise<any>}
     */
    async set(collection, id, doc) {
      const col = getCollection(collection);
      // Store a deep copy
      const copy = JSON.parse(JSON.stringify(doc));
      col.set(String(id), copy);
      return copy;
    },

    /**
     * Delete a document by ID.
     * @param {string} collection
     * @param {string} id
     * @returns {Promise<boolean>}
     */
    async delete(collection, id) {
      const col = getCollection(collection);
      return col.delete(String(id));
    },

    /**
     * List all documents in a collection.
     * @param {string} collection
     * @returns {Promise<Array<any>>}
     */
    async list(collection) {
      const col = getCollection(collection);
      const items = Array.from(col.values());
      return JSON.parse(JSON.stringify(items));
    },

    /**
     * Clear all collections (useful in testing).
     */
    async clear() {
      collections.clear();
    }
  };
}

module.exports = {
  memoryStore
};
